scaffold_files.content:
:root {
    --bg-color: #0a0a12;
    --text-color: #e0e0e0;
    --accent-color: #00f3ff;
    --secondary-color: #7000ff;
    --font-main: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

body {
    margin: 0;
    background-color: var(--bg-color);
    color: var(--text-color);
    font-family: var(--font-main);
    overflow-x: hidden;
}

.main-nav {
    position: fixed;
    top: 0;
    width: 100%;
    background: rgba(10, 10, 18, 0.9);
    backdrop-filter: blur(10px);
    z-index: 100;
    display: flex;
    justify-content: center;
    gap: 2rem;
    padding: 1rem;
    border-bottom: 1px solid var(--accent-color);
}

.main-nav a {
    color: var(--text-color);
    text-decoration: none;
    text-transform: uppercase;
    letter-spacing: 2px;
    transition: color 0.3s;
}

.main-nav a:hover {
    color: var(--accent-color);
}

.scene-container {
    min-height: 100vh;
    padding: 4rem 2rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

/**
 * Audio controller for managing sound effects and ambient audio.
 */
class AudioController {
    constructor() {
        this.sounds = new Map();
        this.globalVolume = 1.0;
    }

    /**
     * Preload and register an audio asset.
     * @param {string} name - Unique identifier for the sound.
     * @param {AudioConfig} config - Audio configuration.
     */
    register(name, config) {
        const audio = new Audio(config.url);
        audio.loop = config.loop;
        audio.volume = config.volume;
        this.sounds.set(name, audio);
    }

    /**
     * Play a registered sound.
     * @param {string} name - Sound identifier.
     * @param {number} [volume] - Optional override volume.
     */
    play(name, volume) {
        const audio = this.sounds.get(name);
        if (!audio) return;
        if (volume !== undefined) audio.volume = volume;
        audio.play().catch(e => console.warn('Audio play failed:', e));
    }

    /**
     * Stop a registered sound.
     * @param {string} name - Sound identifier.
     */
    stop(name) {
        const audio = this.sounds.get(name);
        if (!audio) return;
        audio.pause();
        audio.currentTime = 0;
    }

    /**
     * Set global volume for all sounds.
     * @param {number} vol - Volume between 0 and 1.
     */
    setGlobalVolume(vol) {
        this.globalVolume = vol;
        this.sounds.forEach(audio => {
            audio.volume = vol * (audio._baseVolume || 1);
        });
    }
}

/**
 * Animation loop manager.
 */
class AnimationLoop {
    constructor() {
        this.running = false;
        this.callback = null;
        this.lastTime = 0;
    }

    /**
     * Start the animation loop.
     * @param {(state: AnimationState) => void} callback - Function to call each frame.
     */
    start(callback) {
        if (this.running) return;
        this.running = true;
        this.callback = callback;
        this.lastTime = performance.now();
        this.tick();
    }

    stop() {
        this.running = false;
    }

    tick() {
        if (!this.running) return;
        const now = performance.now();
        const delta = (now - this.lastTime) / 1000;
        this.lastTime = now;
        this.callback({ time: now, delta });
        requestAnimationFrame(() => this.tick());
    }
}

